<?php $__env->startSection('content'); ?><div class="container catalog-shell"><div class="breadcrumbs"><a href="<?php echo e(route('home')); ?>">Início</a> / <span><?php echo e($category?->name ?? 'Coleção completa'); ?></span></div><div class="catalog-heading"><div><span class="eyebrow">ESCOLHAS QUE ENCANTAM</span><h1><?php echo e($category?->name ?? 'Descubra a coleção'); ?></h1><p><?php echo e($products->total()); ?> peças encontradas</p></div><button class="btn btn-light mobile-only" type="button" id="filter-toggle">☷ &nbsp; Filtros</button></div><div class="catalog-content"><aside class="catalog-filters" id="catalog-filters"><h3>Filtrar por</h3><form action="<?php echo e($category?route('category',$category):route('catalog')); ?>" method="get"><div class="filter-group"><label>Pesquisar</label><input type="search" name="q" value="<?php echo e(request()->query('q')); ?>" placeholder="Nome, marca ou SKU"></div><div class="filter-group"><label>Categoria</label><?php if($category): ?><div class="category-filter-current"><?php echo e($category->name); ?> <a href="<?php echo e(route('catalog')); ?>">Ver todas</a></div><?php else: ?><select name="category"><option value="">Todas</option><?php $__currentLoopData = $allCategories; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $c): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option value="<?php echo e($c->id); ?>" <?php if(request()->query('category') == $c->id): echo 'selected'; endif; ?>><?php echo e($c->name); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select><?php endif; ?></div><div class="filter-group"><label>Marca</label><select name="brand"><option value="">Todas as marcas</option><?php $__currentLoopData = $brands; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $brand): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option value="<?php echo e($brand->id); ?>" <?php if(request()->query('brand')==$brand->id): echo 'selected'; endif; ?>><?php echo e($brand->name); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select></div><div class="filter-group"><label>Faixa de preço (R$)</label><div class="price-range"><input type="number" min="0" name="min" value="<?php echo e(request()->query('min')); ?>" placeholder="Mín."><input type="number" min="0" name="max" value="<?php echo e(request()->query('max')); ?>" placeholder="Máx."></div></div><div class="filter-group"><label>Tamanho</label><select name="size"><option value="">Todos</option><?php $__currentLoopData = ['P','M','G','GG','4','6','8','10','36','37','38','39','Único']; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $size): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option <?php if(request()->query('size')==$size): echo 'selected'; endif; ?>><?php echo e($size); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select></div><div class="filter-group"><label>Cor</label><select name="color"><option value="">Todas</option><?php $__currentLoopData = ['Areia','Preto']; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $color): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option <?php if(request()->query('color')==$color): echo 'selected'; endif; ?>><?php echo e($color); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select></div><div class="filter-group"><label class="checkline"><input type="checkbox" name="available" value="1" <?php if(request()->query('available')): echo 'checked'; endif; ?>> Apenas disponíveis</label><label class="checkline"><input type="checkbox" name="sale" value="1" <?php if(request()->query('sale')): echo 'checked'; endif; ?>> Em promoção</label></div><button class="btn btn-dark block" type="submit">Aplicar filtros</button><a class="clear-link" href="<?php echo e($category?route('category',$category):route('catalog')); ?>">Limpar filtros</a></form></aside><div class="catalog-main"><div class="catalog-toolbar"><span>Mostrando <?php echo e($products->firstItem()??0); ?>–<?php echo e($products->lastItem()??0); ?> de <?php echo e($products->total()); ?></span><form method="get"><?php $__currentLoopData = request()->query(); $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $key=>$v): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><?php if(!in_array($key,['sort','page'],true)): ?><?php if(is_scalar($v)): ?><input type="hidden" name="<?php echo e($key); ?>" value="<?php echo e($v); ?>"><?php endif; ?> <?php endif; ?> <?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?><select name="sort" onchange="this.form.submit()"><option value="new">Mais recentes</option><option value="price_asc" <?php if(request()->query('sort')==='price_asc'): echo 'selected'; endif; ?>>Menor preço</option><option value="price_desc" <?php if(request()->query('sort')==='price_desc'): echo 'selected'; endif; ?>>Maior preço</option><option value="popular" <?php if(request()->query('sort')==='popular'): echo 'selected'; endif; ?>>Popularidade</option></select></form></div><?php if($products->isEmpty()): ?><div class="empty-state"><h2>Nenhuma peça encontrada</h2><p>Experimente limpar os filtros para ver mais opções.</p><a href="<?php echo e(route('catalog')); ?>" class="btn btn-dark">Ver coleção</a></div><?php else: ?><div class="products-grid catalog-products"><?php $__currentLoopData = $products; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $product): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><?php echo $__env->make('partials.product-card', array_diff_key(get_defined_vars(), ['__data' => 1, '__path' => 1]))->render(); ?><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></div><div class="pagination"><?php echo e($products->links()); ?></div><?php endif; ?></div></div></div><?php $__env->stopSection(); ?>

